-- Explicit business40001 is not an engine serialization request. All fixtures roll back.
begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
create temp table transport_state(key text primary key,value jsonb);
create function pg_temp.dc_actor(a uuid)returns void language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true)::text is not null$$;
create function pg_temp.dc_cmd(cmd text,body jsonb default '{}',key uuid default gen_random_uuid())returns jsonb language sql as $$select api.frightnight_command('frightnight-2027-test',cmd,body,key)$$;
-- Exact allowlist, not a prefix or a blanket rewrite of serialization_failure.
select ok(app_private.fn_is_domain_conflict('40001',code),'only explicit business message is recognized: '||code)from unnest(array['ALREADY_STARTED','DESTINATION_CONFLICT','IDEMPOTENCY_CONFLICT','RESERVATION_EXPIRED_RESUME','ROUTE_WINDOW_END_RESUME','VERSION_CONFLICT','ZONE_UNAVAILABLE_RESUME','GENERAL_THANKS_ALREADY_SENT','PAYMENT_ALREADY_BOUND','REFUND_ALREADY_REQUESTED','REFUND_PROVIDER_CONFLICT','ORDER_PROVIDER_IMMUTABLE','SANDBOX_RUN_CONFLICT','SANDBOX_REARM_REQUIRED','PROVIDER_CLAIM_RECONCILIATION_REQUIRED','PROVIDER_CLAIM_REQUIRED'])code;
select ok(not app_private.fn_is_domain_conflict('40001','could not serialize access due to concurrent update'),'real engine message is outside business allowlist');
select ok(not app_private.fn_is_domain_conflict('40001','VERSION_CONFLICT: injected detail'),'business prefix with extra data is not trusted');
select ok(not app_private.fn_is_domain_conflict('42501','VERSION_CONFLICT'),'an authorization SQLSTATE cannot become a conflict');
select ok(not app_private.fn_is_domain_conflict(null,null),'missing SQLSTATE/message never becomes a business conflict');
select ok(not has_function_privilege('anon','app_private.fn_is_domain_conflict(text,text)','EXECUTE')and not has_function_privilege('authenticated','app_private.fn_is_domain_conflict(text,text)','EXECUTE')and not has_function_privilege('service_role','app_private.fn_is_domain_conflict(text,text)','EXECUTE'),'classifier has no client or service execution grant');
select is((select count(*)from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='app_private'and p.proname like 'fn_%_transport_impl'and(has_function_privilege('anon',p.oid,'EXECUTE')or has_function_privilege('authenticated',p.oid,'EXECUTE')or has_function_privilege('service_role',p.oid,'EXECUTE'))),0::bigint,'renamed implementations are revoked from every external role');
select is((select count(*)from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='api'and p.proname in('frightnight_command','frightnight_contract_arm','frightnight_payment_claim','frightnight_payment_test_claim','frightnight_payment_bind','frightnight_payment_for_refund','frightnight_payment_refund_record')and p.prosecdef and coalesce(p.proconfig,'{}')@>array['search_path=""']),7::bigint,'all seven public boundaries retain security definer and an empty search path');
select ok(has_function_privilege('authenticated','api.frightnight_command(text,text,jsonb,uuid)','EXECUTE')and not has_function_privilege('service_role','api.frightnight_command(text,text,jsonb,uuid)','EXECUTE'),'command preserves authenticated-only boundary');
select ok(has_function_privilege('service_role',p.oid,'EXECUTE')and not has_function_privilege('anon',p.oid,'EXECUTE')and not has_function_privilege('authenticated',p.oid,'EXECUTE'),'payment boundary stays service-only: '||p.proname)from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='api'and p.proname in('frightnight_contract_arm','frightnight_payment_claim','frightnight_payment_test_claim','frightnight_payment_bind','frightnight_payment_for_refund','frightnight_payment_refund_record');
insert into auth.users(id,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data)select('f7350000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'transport-'||n||'@example.invalid',now(),'{}','{}'from generate_series(1,4)n;
insert into app_private.events(id,slug,title,local_date,price_cents)values('f7350000-0000-0000-0000-000000000010','transport-local-legacy','Synthetic protected transport sentinel','2026-10-31',350);
insert into app_private.event_capabilities(event_id,user_id,capability)values('f7350000-0000-0000-0000-000000000010','f7350000-0000-0000-0000-000000000001','event_admin');
select api.frightnight_bootstrap('frightnight-2027-test','f7350000-0000-0000-0000-000000000001','staging','nocteiuvohesvqbowchw:staging:duindorphalloweenstg')is not null;
select api.frightnight_bootstrap('frightnight-2027-test-transport-copy','f7350000-0000-0000-0000-000000000001','staging','nocteiuvohesvqbowchw:staging:duindorphalloweenstg')is not null;
insert into transport_state values('protected',jsonb_build_object('outbox',(select count(*)from app_private.email_outbox),'payments',(select count(*)from app_private.payment_requests),'auth',(select count(*)from auth.users)));
select pg_temp.dc_actor('f7350000-0000-0000-0000-000000000001');
select pg_temp.dc_cmd('test.seed');
insert into transport_state select 'zone',jsonb_build_object('id',id,'version',version)from app_private.fn_zones where type='candy';
insert into transport_state select 'review',pg_temp.dc_cmd('admin.zone.review',jsonb_build_object('zoneId',(select value->>'id'from transport_state where key='zone'),'expectedVersion',1,'decision','changes_requested','reason','Duidelijke synthetische wijzigingsvraag'),'f7350000-0000-0000-0000-000000000101');
select is((select value#>>'{result,version}'from transport_state where key='review'),'2','valid review version advances exactly once');
select throws_ok($$select pg_temp.dc_cmd('admin.zone.review',jsonb_build_object('zoneId',(select value->>'id'from transport_state where key='zone'),'expectedVersion',1,'decision','approved'))$$,'PT409','VERSION_CONFLICT','stale approved after actual changes_requested leaves boundary once as PT409');
select throws_ok($$select app_private.fn_command_transport_impl('frightnight-2027-test','admin.zone.review',jsonb_build_object('zoneId',(select value->>'id'from transport_state where key='zone'),'expectedVersion',1,'decision','approved'),gen_random_uuid())$$,'40001','VERSION_CONFLICT','owner-only original implementation retains its exact deliberate40001');
select is((select version from app_private.fn_zones where id=(select(value->>'id')::uuid from transport_state where key='zone')),2,'stale public and direct-private attempts never change the current version');
select is((select count(*)from app_private.fn_audit where action='admin.zone.review'),1::bigint,'only successful review has one durable audit');
select is(pg_temp.dc_cmd('admin.zone.review',jsonb_build_object('zoneId',(select value->>'id'from transport_state where key='zone'),'expectedVersion',1,'decision','changes_requested','reason','Duidelijke synthetische wijzigingsvraag'),'f7350000-0000-0000-0000-000000000101')->'result',(select value->'result'from transport_state where key='review'),'same receipt retry preserves stable result without a second mutation');
select throws_ok($$select pg_temp.dc_cmd('admin.zone.review',jsonb_build_object('zoneId',(select value->>'id'from transport_state where key='zone'),'expectedVersion',1,'decision','changes_requested','reason','Changed body'),'f7350000-0000-0000-0000-000000000101')$$,'PT409','IDEMPOTENCY_CONFLICT','changed receipt payload remains non-retryable conflict');
select pg_temp.dc_actor('f7350000-0000-0000-0000-000000000002');
select pg_temp.dc_cmd('registration.save','{"label":"Own transport family","routeType":"lantern","adults":1,"children":1,"maxIntensity":1,"consent":true,"termsVersion":"2027-test-v1"}');
insert into transport_state select 'general',pg_temp.dc_cmd('thanks.general','{"text":"Duurzaam bedankt"}','f7350000-0000-0000-0000-000000000102');
select throws_ok($$select pg_temp.dc_cmd('thanks.general','{"text":"Different"}')$$,'PT409','GENERAL_THANKS_ALREADY_SENT','general feedback conflict also leaves the same command boundary without retry');
select pg_temp.dc_cmd('registration.invite')->'result'is not null;
insert into transport_state select 'adultInvite',pg_temp.dc_cmd('registration.invite')->'result';
select pg_temp.dc_actor('f7350000-0000-0000-0000-000000000003');
select pg_temp.dc_cmd('registration.accept',jsonb_build_object('token',(select value->>'token'from transport_state where key='adultInvite'),'consent',true));
select pg_temp.dc_cmd('thanks.general','{"text":"Duurzaam bedankt"}','f7350000-0000-0000-0000-000000000103');
select pg_temp.dc_actor('f7350000-0000-0000-0000-000000000002');
select pg_temp.dc_cmd('registration.revoke','{"userId":"f7350000-0000-0000-0000-000000000003"}');
select pg_temp.dc_actor('f7350000-0000-0000-0000-000000000003');
select throws_ok($$select pg_temp.dc_cmd('thanks.general','{"text":"Duurzaam bedankt"}','f7350000-0000-0000-0000-000000000103')$$,'42501','REGISTRATION_REQUIRED','current membership revocation is checked before any former private receipt replay');
select pg_temp.dc_actor('f7350000-0000-0000-0000-000000000002');
insert into transport_state select 'order',api.frightnight_payment_claim('frightnight-2027-test','f7350000-0000-0000-0000-000000000002','f7350000-0000-0000-0000-000000000104','contract');
select api.frightnight_payment_bind('frightnight-2027-test',(select(value->>'order_id')::uuid from transport_state where key='order'),'ct_'||(select value->>'order_id'from transport_state where key='order'),null)is not null;
select throws_ok($$select api.frightnight_payment_bind('frightnight-2027-test',(select(value->>'order_id')::uuid from transport_state where key='order'),'ct_f7350000-0000-0000-0000-000000000999',null)$$,'PT409','PAYMENT_ALREADY_BOUND','different provider binding is refused once at service RPC boundary');
select api.frightnight_payment_confirm('frightnight-2027-test','ct_'||(select value->>'order_id'from transport_state where key='order'),'paid',700,'EUR','transport-paid',jsonb_build_object('order_id',(select value->>'order_id'from transport_state where key='order'),'event_id',(select value->>'event_id'from transport_state where key='order'),'testmode',true,'environment','staging'))is not null;
select api.frightnight_payment_for_refund('frightnight-2027-test','f7350000-0000-0000-0000-000000000001',(select(value->>'registration_id')::uuid from transport_state where key='order'),'f7350000-0000-0000-0000-000000000105','Synthetic exact refund request')is not null;
select throws_ok($$select api.frightnight_payment_for_refund('frightnight-2027-test','f7350000-0000-0000-0000-000000000001',(select(value->>'registration_id')::uuid from transport_state where key='order'),gen_random_uuid(),'Different full refund request')$$,'PT409','REFUND_ALREADY_REQUESTED','second refund intent returns non-retryable conflict before external effect');
select api.frightnight_payment_refund_record('frightnight-2027-test','f7350000-0000-0000-0000-000000000001',(select(value->>'order_id')::uuid from transport_state where key='order'),'re_transport','pending','f7350000-0000-0000-0000-000000000105','Synthetic exact refund request')is not null;
select throws_ok($$select api.frightnight_payment_refund_record('frightnight-2027-test','f7350000-0000-0000-0000-000000000001',(select(value->>'order_id')::uuid from transport_state where key='order'),'re_other','refunded','f7350000-0000-0000-0000-000000000105','Synthetic exact refund request')$$,'PT409','REFUND_PROVIDER_CONFLICT','refund acknowledgment retains immutable exact provider binding');
select is((select count(*)from app_private.fn_ledger where kind='receipt'),1::bigint,'boundary failures never duplicate the received payment ledger');
select is((select count(*)from app_private.fn_refunds),1::bigint,'boundary failures leave one authorized durable refund claim');
select throws_ok($$select api.frightnight_contract_arm('frightnight-2027-test-transport-copy','f7350000-0000-0000-0000-000000000001',gen_random_uuid(),'wrong')$$,'PT409','SANDBOX_RUN_CONFLICT','arming stale run is non-retryable at service boundary');
select is((select count(*)from app_private.email_outbox),(select(value->>'outbox')::bigint from transport_state where key='protected'),'transport correction never creates a legacy outbound mail record');
select is((select count(*)from app_private.payment_requests),(select(value->>'payments')::bigint from transport_state where key='protected'),'transport correction changes no historical payment records');
select is((select count(*)from auth.users),(select(value->>'auth')::bigint from transport_state where key='protected'),'transport correction creates or deletes no auth identity');
-- Controlled rollback-only fault at the private delegate: the real public
-- handler must preserve a genuine-shaped engine40001, not rewrite all40001.
create temp sequence transport_attempts;
create or replace function app_private.fn_command_transport_impl(p_slug text,p_command text,p_payload jsonb,p_key uuid)returns jsonb language plpgsql security definer set search_path=''as $$begin perform nextval('pg_temp.transport_attempts');raise serialization_failure using message='could not serialize access due to concurrent update';end$$;
select throws_ok($$select api.frightnight_command('frightnight-2027-test','fixture.engine','{}',gen_random_uuid())$$,'40001','could not serialize access due to concurrent update','unknown engine serialization SQLSTATE and message are rethrown unchanged');
select is((select last_value from transport_attempts),1::bigint,'public transport wrapper delegates once without adding a local retry loop');
select *from finish();
rollback;
